import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {resolvePvpDefence, computePvpBaseDamage, applyPvpFinalDamageStage,
  applyPvpEquipmentReduction} from '../../packages/combat-core/pvp-damage-formulas.mjs';

const close = (actual, expected) => assert.ok(Math.abs(actual - expected) < Math.max(1e-6, Math.abs(expected) * 3e-7), `${actual} != ${expected}`);

// Expectations are hand-calculated from the cited source expressions, not
// generated by a simulation run or copied from output of the implementation.
test('PvP denominator uses attacker level and 0.1 only on its level term', () => {
  const result = resolvePvpDefence({damageType: 0, physicalDefence: 205, attackerLevel: 10});
  assert.equal(result.denominator, 410); assert.equal(result.multiplier, .5);
  const high = resolvePvpDefence({damageType: 0, physicalDefence: 50, attackerLevel: 85});
  assert.equal(high.denominator, 875); close(high.multiplier, 33 / 35);
  assert.notEqual(high.multiplier, 1 - 50 / 5618); // PvE denominator is not PvP.
  assert.notEqual(high.multiplier, 1 - 5 / 875); // No second defense /10.
});

test('physical, magical and mixed damage select the correct defense channel', () => {
  const inputs = {physicalAttack: 1000, magicAttack: 2000, physicalMultiplier: 2, magicMultiplier: 3,
    physicalDefence: 0, magicDefence: 410, attackerLevel: 10};
  assert.equal(computePvpBaseDamage({...inputs, damageType: 0}).amount, 2000);
  assert.equal(computePvpBaseDamage({...inputs, damageType: 1}).amount, 0);
  // (2000+6000)/2 * [1 - (0+410)/2/410] = 2000.
  assert.equal(computePvpBaseDamage({...inputs, damageType: 2}).amount, 2000);
  // Averaging defenses before clamping matters when only one exceeds cap.
  assert.equal(computePvpBaseDamage({...inputs, damageType: 2, magicDefence: 1230}).amount, 0);
});

test('weapon-only damage does not silently substitute total attack', () => {
  const inputs = {physicalAttack: 9000, magicAttack: 9000, physicalMultiplier: 2, magicMultiplier: 3,
    physicalDefence: 0, magicDefence: 0};
  for (const damageType of [3, 4, 5]) assert.equal(computePvpBaseDamage({...inputs, damageType}).reason, 'weapon-attack-undefined');
  assert.equal(computePvpBaseDamage({...inputs, damageType: 3, weaponPhysicalAttack: 100}).amount, 200);
  assert.equal(computePvpBaseDamage({...inputs, damageType: 4, weaponMagicAttack: 200}).amount, 600);
  assert.equal(computePvpBaseDamage({...inputs, damageType: 5, weaponPhysicalAttack: 100, weaponMagicAttack: 200}).amount, 400);
  for (const damageType of [6, 7, -1, 0.5, '0']) assert.equal(computePvpBaseDamage({...inputs, damageType}).reason, 'unsupported-damage-type');
});

test('PENETRATE and IGNORE_DEFENCE bypass base defense; state-only bypass does not', () => {
  for (const bypass of [{penetrate: true}, {ignoreDefence: 1}])
    assert.equal(resolvePvpDefence({...bypass}).multiplier, 1);
  assert.equal(resolvePvpDefence({physicalDefence: 205, attackerLevel: 10, ignoreStateDefence: true}).multiplier, .5);
  assert.equal(resolvePvpDefence({physicalDefence: 205, attackerLevel: 10, defencePierceMultiplier: .5, freezeDefenceMultiplier: .5}).multiplier, .875);
});

test('unknown defense and level remain explicitly unsupported; known zero needs no level', () => {
  assert.equal(resolvePvpDefence({attackerLevel: 85}).reason, 'defence-undefined');
  assert.equal(resolvePvpDefence({physicalDefence: 50}).reason, 'attacker-level-undefined');
  assert.equal(resolvePvpDefence({physicalDefence: 0}).multiplier, 1);
  assert.equal(computePvpBaseDamage({physicalAttack: 1000, physicalMultiplier: 1, physicalDefence: 50}).amount, null);
});

test('ordinary damage permits zero and is not promoted to the special level-damage minimum one', () => {
  assert.equal(computePvpBaseDamage({physicalAttack: 1000, physicalMultiplier: 1, physicalDefence: 10000, attackerLevel: 85}).amount, 0);
  assert.equal(computePvpBaseDamage({physicalAttack: 0, physicalDefence: 0}).amount, 0);
});

test('final attack and defense modifiers use the same pre-modifier damage', () => {
  close(applyPvpFinalDamageStage(1000, {attackFinalMultiplier: 1.2, defenceFinalMultiplier: .76}), 960);
  // Revenge attack changed the attack stat by1.1. Its .9 defense multiplies
  // within the defender's .76 channel; awakening is final attack1.2.
  close(applyPvpFinalDamageStage(1100, {attackFinalMultiplier: 1.2, defenceFinalMultiplier: .76 * .9}), 972.4);
  close(applyPvpFinalDamageStage(1000, {attackFinalMultiplier: .1, defenceFinalMultiplier: .1}), -800);
});

test('equipment reduction is a distinct post-critical stage with a100% cap', () => {
  close(applyPvpEquipmentReduction(1500, .3), 1050);
  assert.equal(applyPvpEquipmentReduction(1500, 1), 0);
  assert.equal(applyPvpEquipmentReduction(1500, 1.5), 0);
  close(applyPvpEquipmentReduction(.75, .3), .525);
});

test('corrupt numeric input is rejected instead of contaminating HP', () => {
  for (const physicalDefence of [-1, NaN, Infinity, '50', {}])
    assert.throws(() => resolvePvpDefence({physicalDefence, attackerLevel: 85}));
  for (const attackerLevel of [0, -1, 85.5, NaN, Infinity, '85'])
    assert.throws(() => resolvePvpDefence({physicalDefence: 50, attackerLevel}));
  for (const physicalAttack of [-1, NaN, Infinity, '1000'])
    assert.throws(() => computePvpBaseDamage({physicalAttack, physicalDefence: 0}));
  assert.throws(() => applyPvpFinalDamageStage(1000, {attackFinalMultiplier: Infinity}));
  assert.throws(() => applyPvpEquipmentReduction(1000, -.1));
});

test('source contract labels provenance and does not invent target measurements', () => {
  const contract = JSON.parse(readFileSync(new URL('../../contracts/pvp-damage-formulas-source-v1.json', import.meta.url)));
  assert.equal(contract.targetClientMeasured, false);
  assert.equal(contract.defence.attackerLevelDefault, null);
  assert.equal(contract.equipment.blanketAttackOrDefenceNormalization, null);
  assert.equal(contract.targetChannels.awakening.attackStat, false);
  assert.equal(contract.targetChannels.revenge.attackStat, true);
});
